const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Cairo, Egypt, approximate center: 30.0444° N, 31.2357° E
  // Define a polygon east of the Nile in Cairo.
  // These coordinates roughly delineate a region east of the Nile, covering parts of Cairo.
  const geometry = ee.Geometry.Polygon(
    [[[31.285854894200637, 30.222722122606834],
      [31.285854894200637, 29.87042831206109],
      [31.50348705301889, 29.87042831206109],
      [31.50348705301889, 30.222722122606834]]], null, false);

  const date1_start = '1984-07-01';
  const date1_end = '1984-07-31';
  const date2_start = '2019-09-01';
  const date2_end = '2019-09-30';

  // Scale for reduceRegion. Landsat resolution is 30m, 1000m or 3000m scale helps avoid timeouts.
  const reducerScale = 1000; 
  const builtUpThreshold = 0.1; // Threshold for NDBI to classify built-up areas

  // Function to mask clouds for Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 5 and 7 are cloud and cloud shadow, respectively.
    // Bits 3 and 2 are clear land and water, respectively.
    const cloudState = qa.bitwiseAnd(1 << 5).eq(0); // Clear cloud
    const cloudShadowState = qa.bitwiseAnd(1 << 7).eq(0); // Clear cloud shadow
    const cirrusState = ee.Image(1); // L5 doesn't have cirrus band, assume clear
    const mask = cloudState.and(cloudShadowState).and(cirrusState);
    return image.updateMask(mask).copyProperties(image);
  }

  // Function to mask clouds for Landsat 8
  function maskL8Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    // Bit 7 is snow/ice, Bit 9 is cirrus (L8 only).
    // Bits 2, 4, 6 are clear land, clear water, clear snow/ice.
    const cloudState = qa.bitwiseAnd(1 << 5).eq(0); // Clear cloud
    const cloudShadowState = qa.bitwiseAnd(1 << 3).eq(0); // Clear cloud shadow
    const cirrusState = qa.bitwiseAnd(1 << 9).eq(0); // Clear cirrus (L8 only)
    const mask = cloudState.and(cloudShadowState).and(cirrusState);
    return image.updateMask(mask).copyProperties(image);
  }

  // Function to calculate NDBI for Landsat 5
  function calculateL5NDBI(image) {
    const swir1 = image.select('B5'); // SWIR1 for L5
    const nir = image.select('B4');  // NIR for L5
    const ndbi = swir1.subtract(nir).divide(swir1.add(nir)).rename('NDBI');
    return image.addBands(ndbi);
  }

  // Function to calculate NDBI for Landsat 8
  function calculateL8NDBI(image) {
    const swir1 = image.select('B6'); // SWIR1 for L8
    const nir = image.select('B5');  // NIR for L8
    const ndbi = swir1.subtract(nir).divide(swir1.add(nir)).rename('NDBI');
    return image.addBands(ndbi);
  }

  // 2. Data Acquisition & Check - 1984 (Landsat 5)
  let col1 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(geometry)
    .filterDate(date1_start, date1_end)
    .map(maskL5Clouds)
    .map(calculateL5NDBI)
    .select('NDBI');

  const col1Size = await col1.size().getInfo();
  if (col1Size === 0) {
    console.log("No Landsat 5 images found for July 1984. Trying wider date range for 1984.");
    col1 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
      .filterBounds(geometry)
      .filterDate('1984-06-01', '1984-08-31') // Wider date range
      .map(maskL5Clouds)
      .map(calculateL5NDBI)
      .select('NDBI');
    if (await col1.size().getInfo() === 0) {
        console.log("No data for 1984 after trying wider range.");
        console.log("C1");
        return;
    }
  }
  const img1 = col1.median();

  // 3. Processing - 1984
  const count1 = await img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: reducerScale,
    maxPixels: 1e9,
  }).get('NDBI').getInfo();

  if (count1 === 0) {
    console.log(`1984 Images: ${col1Size} (No valid pixels after masking).`);
    console.log("C2");
    return;
  }

  // 4. Calculation - 1984 Built-up Area
  const builtUp1_mask = img1.gt(builtUpThreshold);
  const area1_sqm = builtUp1_mask.multiply(ee.Image.pixelArea());
  const builtUpArea1 = await area1_sqm.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: reducerScale,
    maxPixels: 1e9,
  }).get('NDBI').getInfo();

  if (builtUpArea1 === null || isNaN(builtUpArea1)) {
    console.log("1984 Built-up area calculation failed (null/NaN).");
    console.log("C3");
    return;
  }
  const builtUpArea1_km2 = builtUpArea1 / 1e6;

  // 2. Data Acquisition & Check - 2019 (Landsat 8)
  let col2 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
    .filterBounds(geometry)
    .filterDate(date2_start, date2_end)
    .map(maskL8Clouds)
    .map(calculateL8NDBI)
    .select('NDBI');

  const col2Size = await col2.size().getInfo();
  if (col2Size === 0) {
    console.log("No Landsat 8 images found for September 2019. Trying wider date range for 2019.");
    col2 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
      .filterBounds(geometry)
      .filterDate('2019-08-01', '2019-10-31') // Wider date range
      .map(maskL8Clouds)
      .map(calculateL8NDBI)
      .select('NDBI');
    if (await col2.size().getInfo() === 0) {
        console.log("No data for 2019 after trying wider range.");
        console.log("C1");
        return;
    }
  }
  const img2 = col2.median();

  // 3. Processing - 2019
  const count2 = await img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: reducerScale,
    maxPixels: 1e9,
  }).get('NDBI').getInfo();

  if (count2 === 0) {
    console.log(`2019 Images: ${col2Size} (No valid pixels after masking).`);
    console.log("C2");
    return;
  }

  // 4. Calculation - 2019 Built-up Area
  const builtUp2_mask = img2.gt(builtUpThreshold);
  const area2_sqm = builtUp2_mask.multiply(ee.Image.pixelArea());
  const builtUpArea2 = await area2_sqm.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: reducerScale,
    maxPixels: 1e9,
  }).get('NDBI').getInfo();

  if (builtUpArea2 === null || isNaN(builtUpArea2)) {
    console.log("2019 Built-up area calculation failed (null/NaN).");
    console.log("C3");
    return;
  }
  const builtUpArea2_km2 = builtUpArea2 / 1e6;

  // 5. Validation & Final Answer
  console.log(`1984 Images: ${col1Size}, Valid Pixels: ${count1}, Built-up Area: ${builtUpArea1_km2.toFixed(2)} km²`);
  console.log(`2019 Images: ${col2Size}, Valid Pixels: ${count2}, Built-up Area: ${builtUpArea2_km2.toFixed(2)} km²`);

  if (builtUpArea2_km2 > builtUpArea1_km2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
